// Isolated browser harness: both databases are in memory; no work DB imports.
import {migrateReportRequests} from '../../src/reports/migrations.js';
import {REPORT_FIELDS} from '../../src/reports/normalization.js';
import {createReportLinkRouter} from '../../src/checklists/report-link-routes.js';
import express from 'express';
import session from 'express-session';
import Database from 'better-sqlite3';
import {createAuthService} from '../../src/auth.js';
import {migrateChecklistDatabase} from '../../src/checklists/migrations.js';
import {createRunRouter} from '../../src/checklists/run-routes.js';
import {createTemplateService} from '../../src/checklists/templates.js';
import {createShiftService} from '../../src/checklists/shifts.js';
import {templateFixture} from './checklist-template.js';
import {scheduleFixture} from './checklist-schedule.js';
const db=new Database(':memory:'),journal=new Database(':memory:');db.pragma('foreign_keys=ON');migrateChecklistDatabase(db);
journal.exec(`CREATE TABLE roles(name TEXT PRIMARY KEY,label TEXT,view_checklists INTEGER,create_checklists INTEGER,edit_own_checklists INTEGER,manage_checklists INTEGER,create_reports_from_checklist INTEGER,view_all_reports INTEGER);
INSERT INTO roles VALUES('technician','Texnik',1,1,1,0,1,1),('employee','İstifadəçi',1,0,0,0,0,0),('admin','Admin',1,1,1,1,1,1);
CREATE TABLE users(id INTEGER PRIMARY KEY,username TEXT,full_name TEXT,role TEXT,active INTEGER DEFAULT 1,deleted INTEGER DEFAULT 0);
INSERT INTO users(id,username,full_name,role) VALUES(1,'tech','Tural Orucov','technician'),(2,'employee','Employee','employee'),(3,'admin','Admin User','admin'),(4,'othertech','Other Technician','technician');`);
journal.exec(`CREATE TABLE reports(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,owner_user_id INTEGER,${REPORT_FIELDS.map(f=>`${f} TEXT DEFAULT ''`).join(',')});`);migrateReportRequests(journal);
let instant=new Date('2026-09-19T00:00:00Z');const now=()=>instant;
const templates=createTemplateService(db);let v=templates.create({code:'TEST',name:'Daily'},1);v=templates.update(v.id,{...templateFixture,sections:templateFixture.sections.map((s,i)=>({...s,service_name:process.env.REPORT_MISSING&&i===0?'':s.service_name})),revision:1});templates.publish(v.id,2,1);
const shifts=createShiftService(db,now),s=shifts.create(scheduleFixture,1);shifts.publish(s.id,1,1);instant=new Date('2026-09-19T05:00:00Z');
const app=express(),auth=createAuthService(journal,'browser-test-only');app.use(express.json());app.use(session({secret:'browser-test-only',resave:false,saveUninitialized:false}));
app.get('/api/me',auth.requireAuth,(_q,s)=>s.json(auth.userPayload(s.locals.user)));
app.get('/api/reports',auth.requireAuth,(_q,s)=>s.json(auth.can(s.locals.user,'view_all_reports')?journal.prepare('SELECT * FROM reports').all():[]));
app.post('/test-expire',(_q,s)=>{instant=new Date('2026-09-19T16:00:01Z');s.json({ok:true});});
app.post('/test-fail-link',(q,s)=>{if(q.body.enabled)db.exec("CREATE TRIGGER fail_browser_link BEFORE UPDATE OF state ON checklist_report_links WHEN NEW.state='linked' BEGIN SELECT RAISE(ABORT,'fault'); END");else db.exec('DROP TRIGGER IF EXISTS fail_browser_link');s.json({ok:true});});
app.post('/test-delete-report',(q,s)=>{journal.prepare('DELETE FROM reports WHERE id=?').run(q.body.id);s.json({ok:true});});
app.use('/api',createReportLinkRouter({available:true,db},journal,auth,{write(){}},()=>{},now));
app.use('/api',createRunRouter({available:true,db},auth,{write(){}},now));app.use(express.static('public'));app.use((e:any,_q:express.Request,s:express.Response,_n:express.NextFunction)=>s.status(500).json({error:'Nasazlıq yaratmaq mümkün olmadı'}));
const server=app.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({port:(server.address() as any).port,tech:auth.signAuthToken(1),employee:auth.signAuthToken(2),admin:auth.signAuthToken(3),othertech:auth.signAuthToken(4)})));
process.on('SIGTERM',()=>{server.closeAllConnections();server.close(()=>{db.close();journal.close();process.exit(0);});});
